create or replace function private.checkout_create_order_audited(p_shipping jsonb,p_payment_method public.payment_method,p_currency public.currency_code,p_delivery_speed public.delivery_speed,p_items jsonb,p_coupon_code text,p_idempotency_key text) returns uuid language plpgsql set search_path to '' as $$ declare v_order uuid; begin if p_idempotency_key is null or p_idempotency_key !~ '^[0-9a-fA-F-]{36}$' then raise exception 'valid UUID idempotency key required'; end if; perform pg_catalog.set_config('yalla.checkout_order_id',p_idempotency_key,true); v_order := private.checkout_create_order(p_shipping,p_payment_method,p_currency,p_delivery_speed,p_items,p_coupon_code,p_idempotency_key); return v_order; end; $$;
